void sh_css_set_shading_settings ( struct ia_css_isp_parameters * params , const struct ia_css_shading_settings * settings ) { assert ( params ) ; ia_css_debug_dtrace ( IA_CSS_DEBUG_TRACE , "ia_css_set_shading_settings() enter: settings.enable_shading_table_conversion=%d\n" , settings -> enable_shading_table_conversion ) ; params -> shading_settings = * settings ; params -> shading_settings_changed = true ; ia_css_debug_dtrace ( IA_CSS_DEBUG_TRACE , "ia_css_set_shading_settings() leave: return_void\n" ) ; } 